<?php
$ec=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
$patient=(int)$context['patient']['id'];$base=$context['base'];$draft=$context['draft'];$cs=$context['summary'];$assessment=$context['assessment'];$published=$context['published'];
$fmt=static fn($d)=>$d?date('d/m/Y H:i',(int)strtotime((string)$d)):'Data não registrada';
$sourceLabel=implode('; ',$context['safety_sources']);
?>
<details id="<?= $ec($contextId) ?>" class="clinical-context op-context-panel" data-testid="clinical-context" data-clinical-context data-patient-id="<?= $patient ?>" data-clinic-id="<?= (int)$context['clinic_id'] ?>" data-context-revision="<?= $ec($context['revision']) ?>" data-clinical-source-label="<?= $ec($sourceLabel?:'Alergias sem fonte registrada; requer avaliação') ?>">
<summary><span class="clinical-context__title">Contexto clínico · <?= $ec($context['patient']['name']) ?></span><span class="clinical-context__hint"><?= $ec($context['clinic_name']) ?> · <?= $base?'Anamnese vigente v'.(int)$base['version']:'Sem anamnese concluída' ?><?= $draft?' · Rascunho v'.(int)$draft['version'].' pendente':'' ?></span></summary>
<p class="op-context-identity">Informações registradas no prontuário não comprovam, por si só, diagnóstico ou confirmação independente do relato. Confira a fonte e a revisão profissional.</p>
<dl class="clinical-context__grid">
<div class="clinical-context__item<?= ($cs['allergy_state']??'')==='recorded'?' is-alert':'' ?>" data-testid="context-allergies"><dt>Alergias — revisão de segurança</dt><dd><strong><?= $ec($cs['allergy_label']??'Não avaliado') ?></strong>
<?php foreach($context['allergy_sources'] as $source): ?><p><span><?= $ec($source['value']) ?></span><br><a href="<?= $ec($source['url']) ?>"><?= $ec($source['label']) ?></a><?php if($source['date']): ?><br><?= $ec($fmt($source['date'])) ?><?= $source['author']?' · '.$ec($source['author']):'' ?><?php endif; ?></p><?php endforeach; ?>
<?php if(!$context['allergy_sources']&&empty($cs['allergy_review'])): ?><p>Não registrado. Ausência de informação não confirma ausência de alergias.</p><?php endif; ?>
<?php foreach($cs['allergy_review']??[] as $review): ?><p class="clinical-context__warn"><strong>Exige revisão clínica:</strong> <?= $ec($review['message']) ?></p><?php endforeach; ?>
<?php if($context['registration_hint']): ?><p>Observações do cadastro mencionam alergia ou intolerância; confira o relato. O texto livre não foi convertido em diagnóstico.</p><?php endif; ?>
</dd></div>
<div class="clinical-context__item" data-testid="context-restrictions"><dt>Restrições relatadas e registradas</dt><dd><?= $ec($context['restrictions']?:'Não registrado em anamnese concluída') ?></dd></div>
<div class="clinical-context__item" data-testid="context-goals"><dt>Metas e objetivos registrados</dt><dd><?= $ec($context['objectives']?:'Não registrado em anamnese concluída') ?></dd></div>
<div class="clinical-context__item" data-testid="context-anamnesis"><dt>Anamnese vigente</dt><dd><?php if($base): ?><a href="/pacientes/<?= $patient ?>/anamnese?version=<?= (int)$base['version'] ?>">v<?= (int)$base['version'] ?> concluída</a> · <?= $ec($fmt($base['created_at'])) ?> · <?= $ec($base['professional_name']?:'Autor não registrado') ?><?php else: ?>Nenhuma versão concluída<?php endif; ?>
<?php if($draft): ?><p data-context-draft>Rascunho v<?= (int)$draft['version'] ?> · salvo em <?= $ec($fmt($draft['created_at'])) ?>. Não substitui a versão vigente. Alergias acrescentadas continuam exigindo revisão de segurança. <a href="/pacientes/<?= $patient ?>/anamnese">Retomar anamnese</a></p><?php endif; ?></dd></div>
<div class="clinical-context__item" data-testid="context-assessment"><dt>Última avaliação física documentada</dt><dd><?php if($assessment): ?><a href="/pacientes/<?= $patient ?>/antropometria">Avaliação #<?= (int)$assessment['id'] ?></a> · <?= $ec($fmt($assessment['assessed_at']?:$assessment['created_at'])) ?><br><?= $assessment['weight_kg']!==null?$ec(number_format((float)$assessment['weight_kg'],1,',','.')).' kg':'Peso não registrado' ?><?= $assessment['bmi']!==null?' · IMC '.$ec(number_format((float)$assessment['bmi'],1,',','.')):'' ?><?php else: ?>Não registrada<?php endif; ?></dd></div>
<?php $cons=$context['consultation']??null;$consApp=$cons['appointment']??null;$consWhen=static fn($d)=>date('d/m/Y \\à\\s H:i',(int)strtotime((string)$d));$onConsultation=$consApp&&preg_match('#^/consulta/'.(int)$consApp['id'].'(?:[/?]|$)#',(string)($_SERVER['REQUEST_URI']??'')); ?>
<div class="clinical-context__item" data-testid="context-appointment" data-state="<?= $ec($cons['state']??'unavailable') ?>"><dt>Consulta</dt><dd><?php if($cons===null): ?><span class="clinical-context__missing">Agenda indisponível no momento. Confira na Agenda.</span><?php elseif($consApp&&$cons['state']==='continue'): ?><strong>Em andamento</strong> · agendada para <?= $ec($consWhen($consApp['scheduled_at'])) ?><?php if(!$onConsultation): ?><br><a href="/consulta/<?= (int)$consApp['id'] ?>">Abrir consulta</a><?php endif; ?><?php elseif($consApp&&$cons['state']==='start_today'): ?><strong>Hoje</strong> às <?= $ec(date('H:i',(int)strtotime((string)$consApp['scheduled_at']))) ?><?php elseif($consApp): ?><strong>Próxima</strong>: <?= $ec($consWhen($consApp['scheduled_at'])) ?><?php else: ?><span class="clinical-context__missing">Nenhuma consulta agendada</span><?php endif; ?>
<?php if(!empty($cons['last'])): ?><br><span class="clinical-context__src">Última consulta concluída: <?= $ec(date('d/m/Y',(int)strtotime((string)($cons['last']['effective_at']??$cons['last']['scheduled_at'])))) ?></span><?php endif; ?></dd></div>
<div class="clinical-context__item" data-testid="context-published-plan"><dt>Plano publicado vigente</dt><dd><?php if($published): ?><a href="/planos/<?= (int)$published['meal_plan_id'] ?>">v<?= (int)$published['version_number'] ?> publicada</a> · <?= $ec($fmt($published['published_at'])) ?><?php else: ?>Nenhum plano publicado. Rascunhos não são apresentados como vigentes.<?php endif; ?></dd></div>
<div class="clinical-context__item"><dt>Medicamentos relatados na anamnese concluída</dt><dd><?= $ec($context['medications']?:'Não registrado') ?></dd></div>
</dl>
<?= \ClyoNutri\Application\View\AdaptiveSummary::render($db,$patient,$cs['adaptive_summary']??[]) ?>
